// FreeLang v2.6.0: Complete Grammar Specification
// 목표: FreeLang 언어의 완전한 문법을 메타프로그래밍으로 정의
// 규모: 600줄 (Day 1-2)
// 작성자: Agent 8

// ============================================================================
// PART 1: Token & Lexical Elements (100줄)
// ============================================================================

struct Token {
    type: string,      // KEYWORD, IDENTIFIER, NUMBER, STRING, OPERATOR, PUNCTUATION
    lexeme: string,    // 실제 토큰 텍스트
    line: i32,         // 라인 번호
    column: i32        // 컬럼 번호
}

struct TokenType {
    // 키워드 (40개)
    keywords: array,
    // KEYWORD tokens: fn, let, const, struct, trait, impl, match, if, else, while, for, break, continue,
    // return, pub, private, module, use, as, where, super, self, crate, unsafe, async, await, move, dyn, ref, mut

    // 연산자 & 특수 문자
    operators: array,   // +, -, *, /, %, ==, !=, <, >, <=, >=, &&, ||, !, &, |, ^, <<, >>
    punctuation: array  // (, ), {, }, [, ], ;, :, ,, ., ->, =>, ::, =, @, #
}

fn create_token_type() -> TokenType {
    let mut types = TokenType {
        keywords: array,
        operators: array,
        punctuation: array
    };

    // 키워드 초기화 (40개)
    let keywords = array[
        "fn", "let", "const", "struct", "trait", "impl",
        "match", "if", "else", "while", "for", "break", "continue",
        "return", "pub", "private", "module", "use", "as", "where",
        "super", "self", "crate", "unsafe", "async", "await", "move",
        "dyn", "ref", "mut", "static", "type", "enum", "union",
        "in", "loop", "default", "abstract", "virtual", "final"
    ];

    types.keywords = keywords;
    return types;
}

// ============================================================================
// PART 2: Grammar Rules - 상향식 파서 (200줄)
// ============================================================================

struct GrammarRule {
    name: string,           // 규칙 이름 (e.g., "expression", "statement")
    alternatives: array,    // 여러 선택지
    first_set: array,       // FIRST 집합 (LL1 파싱)
    follow_set: array       // FOLLOW 집합
}

struct Parser {
    tokens: array,
    current: i32,           // 현재 토큰 위치
    errors: array
}

// 규칙 1: Program (최상위)
// program := (declaration | statement)* EOF
fn parse_program(parser: Parser) -> any {
    let mut items = array;

    while parser.current < length(parser.tokens) {
        let token = parser.tokens[parser.current];

        // declaration vs statement 판단
        if token.type == "KEYWORD" && (token.lexeme == "fn" || token.lexeme == "struct" || token.lexeme == "trait") {
            // declaration
            let decl = parse_declaration(parser);
            push(items, decl);
        } else {
            // statement
            let stmt = parse_statement(parser);
            push(items, stmt);
        }
    }

    return items;
}

// 규칙 2: Declaration
// declaration := fn_decl | struct_decl | trait_decl | impl_block | module_decl
fn parse_declaration(parser: Parser) -> any {
    let token = parser.tokens[parser.current];

    if token.lexeme == "fn" {
        return parse_fn_decl(parser);
    } else if token.lexeme == "struct" {
        return parse_struct_decl(parser);
    } else if token.lexeme == "trait" {
        return parse_trait_decl(parser);
    } else if token.lexeme == "impl" {
        return parse_impl_block(parser);
    } else if token.lexeme == "module" {
        return parse_module_decl(parser);
    }

    return {type: "error", message: "unknown declaration"};
}

// 규칙 3: Function Declaration
// fn_decl := "fn" IDENT "(" params? ")" ("->" type)? "{" block "}"
fn parse_fn_decl(parser: Parser) -> any {
    // consume "fn"
    parser.current = parser.current + 1;

    // parse function name
    let name_token = parser.tokens[parser.current];
    let name = name_token.lexeme;
    parser.current = parser.current + 1;

    // expect "("
    parser.current = parser.current + 1;

    // parse parameters
    let params = parse_params(parser);

    // expect ")"
    parser.current = parser.current + 1;

    // parse return type (optional)
    let return_type = null;
    if parser.tokens[parser.current].lexeme == "->" {
        parser.current = parser.current + 1;
        return_type = parse_type(parser);
    }

    // expect "{"
    parser.current = parser.current + 1;

    // parse function body
    let body = parse_block(parser);

    // expect "}"
    parser.current = parser.current + 1;

    return {
        type: "fn_decl",
        name: name,
        params: params,
        return_type: return_type,
        body: body
    };
}

// 규칙 4: Parameters
// params := pattern (":" type)? ("," pattern (":" type)?)*
fn parse_params(parser: Parser) -> array {
    let mut params = array;

    while parser.tokens[parser.current].lexeme != ")" {
        let param_name = parser.tokens[parser.current].lexeme;
        parser.current = parser.current + 1;

        // expect ":"
        parser.current = parser.current + 1;

        // parse type
        let param_type = parse_type(parser);

        push(params, {name: param_name, type: param_type});

        // check for "," or ")"
        if parser.tokens[parser.current].lexeme == "," {
            parser.current = parser.current + 1;
        }
    }

    return params;
}

// 규칙 5: Type
// type := IDENT | type "[" type "]" | type "->" type | "(" type_list ")" | "{" struct_members "}"
fn parse_type(parser: Parser) -> any {
    let token = parser.tokens[parser.current];

    if token.type == "IDENTIFIER" {
        let type_name = token.lexeme;
        parser.current = parser.current + 1;

        // check for generics: Type<T, U>
        if parser.tokens[parser.current].lexeme == "<" {
            parser.current = parser.current + 1;
            let generics = array;
            while parser.tokens[parser.current].lexeme != ">" {
                push(generics, parse_type(parser));
                if parser.tokens[parser.current].lexeme == "," {
                    parser.current = parser.current + 1;
                }
            }
            parser.current = parser.current + 1; // consume ">"

            return {type: "generic", name: type_name, params: generics};
        }

        return {type: "named", name: type_name};
    }

    return {type: "error", message: "invalid type"};
}

// ============================================================================
// PART 3: Expression Grammar (150줄)
// ============================================================================

// 규칙 6: Expression (우선순위)
// expr := match_expr | assignment_expr
// assignment_expr := logical_or_expr (("=" | "+=" | "-=" | ...) logical_or_expr)*
// logical_or_expr := logical_and_expr ("||" logical_and_expr)*
// logical_and_expr := equality_expr ("&&" equality_expr)*
// equality_expr := comparison_expr (("==" | "!=") comparison_expr)*
// comparison_expr := additive_expr (("<" | ">" | "<=" | ">=") additive_expr)*
// additive_expr := multiplicative_expr (("+" | "-") multiplicative_expr)*
// multiplicative_expr := unary_expr (("*" | "/" | "%") unary_expr)*
// unary_expr := ("!" | "-" | "&" | "*") unary_expr | postfix_expr
// postfix_expr := call_expr | index_expr | member_expr | primary_expr

fn parse_expr(parser: Parser) -> any {
    // 최고 우선순위 진입점
    return parse_assignment_expr(parser);
}

fn parse_assignment_expr(parser: Parser) -> any {
    let left = parse_logical_or_expr(parser);

    // 할당 연산자 체크
    let token = parser.tokens[parser.current];
    if token.lexeme == "=" || token.lexeme == "+=" || token.lexeme == "-=" {
        let op = token.lexeme;
        parser.current = parser.current + 1;
        let right = parse_assignment_expr(parser);

        return {
            type: "assignment",
            operator: op,
            left: left,
            right: right
        };
    }

    return left;
}

fn parse_logical_or_expr(parser: Parser) -> any {
    let mut left = parse_logical_and_expr(parser);

    while parser.tokens[parser.current].lexeme == "||" {
        parser.current = parser.current + 1;
        let right = parse_logical_and_expr(parser);
        left = {
            type: "binary",
            operator: "||",
            left: left,
            right: right
        };
    }

    return left;
}

fn parse_logical_and_expr(parser: Parser) -> any {
    let mut left = parse_equality_expr(parser);

    while parser.tokens[parser.current].lexeme == "&&" {
        parser.current = parser.current + 1;
        let right = parse_equality_expr(parser);
        left = {
            type: "binary",
            operator: "&&",
            left: left,
            right: right
        };
    }

    return left;
}

fn parse_equality_expr(parser: Parser) -> any {
    let mut left = parse_comparison_expr(parser);

    let token = parser.tokens[parser.current];
    while token.lexeme == "==" || token.lexeme == "!=" {
        let op = token.lexeme;
        parser.current = parser.current + 1;
        let right = parse_comparison_expr(parser);
        left = {
            type: "binary",
            operator: op,
            left: left,
            right: right
        };
    }

    return left;
}

fn parse_comparison_expr(parser: Parser) -> any {
    let mut left = parse_additive_expr(parser);

    let token = parser.tokens[parser.current];
    while token.lexeme == "<" || token.lexeme == ">" || token.lexeme == "<=" || token.lexeme == ">=" {
        let op = token.lexeme;
        parser.current = parser.current + 1;
        let right = parse_additive_expr(parser);
        left = {
            type: "binary",
            operator: op,
            left: left,
            right: right
        };
    }

    return left;
}

fn parse_additive_expr(parser: Parser) -> any {
    let mut left = parse_multiplicative_expr(parser);

    while parser.tokens[parser.current].lexeme == "+" || parser.tokens[parser.current].lexeme == "-" {
        let op = parser.tokens[parser.current].lexeme;
        parser.current = parser.current + 1;
        let right = parse_multiplicative_expr(parser);
        left = {
            type: "binary",
            operator: op,
            left: left,
            right: right
        };
    }

    return left;
}

fn parse_multiplicative_expr(parser: Parser) -> any {
    let mut left = parse_unary_expr(parser);

    while parser.tokens[parser.current].lexeme == "*" || parser.tokens[parser.current].lexeme == "/" || parser.tokens[parser.current].lexeme == "%" {
        let op = parser.tokens[parser.current].lexeme;
        parser.current = parser.current + 1;
        let right = parse_unary_expr(parser);
        left = {
            type: "binary",
            operator: op,
            left: left,
            right: right
        };
    }

    return left;
}

fn parse_unary_expr(parser: Parser) -> any {
    let token = parser.tokens[parser.current];

    if token.lexeme == "!" || token.lexeme == "-" || token.lexeme == "&" || token.lexeme == "*" {
        let op = token.lexeme;
        parser.current = parser.current + 1;
        let operand = parse_unary_expr(parser);

        return {
            type: "unary",
            operator: op,
            operand: operand
        };
    }

    return parse_postfix_expr(parser);
}

fn parse_postfix_expr(parser: Parser) -> any {
    let mut expr = parse_primary_expr(parser);

    // postfix 연산자 처리
    loop {
        let token = parser.tokens[parser.current];

        if token.lexeme == "(" {
            // function call
            parser.current = parser.current + 1;
            let args = parse_arg_list(parser);
            parser.current = parser.current + 1; // consume ")"
            expr = {
                type: "call",
                callee: expr,
                args: args
            };
        } else if token.lexeme == "[" {
            // array index
            parser.current = parser.current + 1;
            let index = parse_expr(parser);
            parser.current = parser.current + 1; // consume "]"
            expr = {
                type: "index",
                array: expr,
                index: index
            };
        } else if token.lexeme == "." {
            // member access
            parser.current = parser.current + 1;
            let member = parser.tokens[parser.current].lexeme;
            parser.current = parser.current + 1;
            expr = {
                type: "member",
                object: expr,
                member: member
            };
        } else {
            break;
        }
    }

    return expr;
}

fn parse_primary_expr(parser: Parser) -> any {
    let token = parser.tokens[parser.current];

    if token.type == "NUMBER" {
        parser.current = parser.current + 1;
        return {type: "literal", value: token.lexeme, kind: "number"};
    } else if token.type == "STRING" {
        parser.current = parser.current + 1;
        return {type: "literal", value: token.lexeme, kind: "string"};
    } else if token.type == "IDENTIFIER" {
        parser.current = parser.current + 1;
        return {type: "identifier", name: token.lexeme};
    } else if token.lexeme == "(" {
        parser.current = parser.current + 1;
        let expr = parse_expr(parser);
        parser.current = parser.current + 1; // consume ")"
        return expr;
    } else if token.lexeme == "{" {
        // block expression
        return parse_block(parser);
    }

    return {type: "error", message: "invalid expression"};
}

// ============================================================================
// PART 4: Statement Grammar (100줄)
// ============================================================================

// statement := expr_stmt | let_stmt | if_stmt | while_stmt | for_stmt | match_stmt | block
fn parse_statement(parser: Parser) -> any {
    let token = parser.tokens[parser.current];

    if token.lexeme == "let" {
        return parse_let_stmt(parser);
    } else if token.lexeme == "if" {
        return parse_if_stmt(parser);
    } else if token.lexeme == "while" {
        return parse_while_stmt(parser);
    } else if token.lexeme == "for" {
        return parse_for_stmt(parser);
    } else if token.lexeme == "match" {
        return parse_match_stmt(parser);
    } else if token.lexeme == "{" {
        return parse_block(parser);
    } else {
        // expression statement
        let expr = parse_expr(parser);
        if parser.tokens[parser.current].lexeme == ";" {
            parser.current = parser.current + 1;
        }
        return {type: "expr_stmt", expr: expr};
    }
}

fn parse_let_stmt(parser: Parser) -> any {
    parser.current = parser.current + 1; // consume "let"

    let name = parser.tokens[parser.current].lexeme;
    parser.current = parser.current + 1;

    let type_annotation = null;
    if parser.tokens[parser.current].lexeme == ":" {
        parser.current = parser.current + 1;
        type_annotation = parse_type(parser);
    }

    let init = null;
    if parser.tokens[parser.current].lexeme == "=" {
        parser.current = parser.current + 1;
        init = parse_expr(parser);
    }

    if parser.tokens[parser.current].lexeme == ";" {
        parser.current = parser.current + 1;
    }

    return {
        type: "let_stmt",
        name: name,
        type_annotation: type_annotation,
        init: init
    };
}

fn parse_if_stmt(parser: Parser) -> any {
    parser.current = parser.current + 1; // consume "if"

    let cond = parse_expr(parser);
    let then_block = parse_block(parser);

    let else_block = null;
    if parser.tokens[parser.current].lexeme == "else" {
        parser.current = parser.current + 1;

        if parser.tokens[parser.current].lexeme == "if" {
            else_block = parse_if_stmt(parser);
        } else {
            else_block = parse_block(parser);
        }
    }

    return {
        type: "if_stmt",
        condition: cond,
        then_block: then_block,
        else_block: else_block
    };
}

fn parse_while_stmt(parser: Parser) -> any {
    parser.current = parser.current + 1; // consume "while"

    let cond = parse_expr(parser);
    let body = parse_block(parser);

    return {
        type: "while_stmt",
        condition: cond,
        body: body
    };
}

fn parse_for_stmt(parser: Parser) -> any {
    parser.current = parser.current + 1; // consume "for"

    let pattern = parser.tokens[parser.current].lexeme;
    parser.current = parser.current + 1;

    parser.current = parser.current + 1; // consume "in"

    let iter = parse_expr(parser);
    let body = parse_block(parser);

    return {
        type: "for_stmt",
        pattern: pattern,
        iterable: iter,
        body: body
    };
}

fn parse_match_stmt(parser: Parser) -> any {
    parser.current = parser.current + 1; // consume "match"

    let expr = parse_expr(parser);

    parser.current = parser.current + 1; // consume "{"

    let mut arms = array;
    while parser.tokens[parser.current].lexeme != "}" {
        let pattern = parse_pattern(parser);

        parser.current = parser.current + 1; // consume "=>"

        let body = parse_expr(parser);

        push(arms, {pattern: pattern, body: body});

        if parser.tokens[parser.current].lexeme == "," {
            parser.current = parser.current + 1;
        }
    }

    parser.current = parser.current + 1; // consume "}"

    return {
        type: "match_stmt",
        expr: expr,
        arms: arms
    };
}

fn parse_block(parser: Parser) -> any {
    parser.current = parser.current + 1; // consume "{"

    let mut stmts = array;
    while parser.tokens[parser.current].lexeme != "}" {
        push(stmts, parse_statement(parser));
    }

    parser.current = parser.current + 1; // consume "}"

    return {type: "block", statements: stmts};
}

// ============================================================================
// PART 5: Helper Functions (50줄)
// ============================================================================

fn parse_pattern(parser: Parser) -> any {
    let token = parser.tokens[parser.current];

    if token.type == "IDENTIFIER" {
        let name = token.lexeme;
        parser.current = parser.current + 1;
        return {type: "identifier_pattern", name: name};
    } else if token.lexeme == "_" {
        parser.current = parser.current + 1;
        return {type: "wildcard_pattern"};
    }

    return {type: "error", message: "invalid pattern"};
}

fn parse_arg_list(parser: Parser) -> array {
    let mut args = array;

    while parser.tokens[parser.current].lexeme != ")" {
        push(args, parse_expr(parser));

        if parser.tokens[parser.current].lexeme == "," {
            parser.current = parser.current + 1;
        }
    }

    return args;
}

fn parse_struct_decl(parser: Parser) -> any {
    // stub
    return {type: "struct_decl"};
}

fn parse_trait_decl(parser: Parser) -> any {
    // stub
    return {type: "trait_decl"};
}

fn parse_impl_block(parser: Parser) -> any {
    // stub
    return {type: "impl_block"};
}

fn parse_module_decl(parser: Parser) -> any {
    // stub
    return {type: "module_decl"};
}

// FreeLang v2.6.0: Complete Semantics Specification
// 목표: 타입 시스템, 타입 추론, 제약 전파, 의미론 검증
// 규모: 600줄 (Day 3-4)
// 작성자: Agent 8

// ============================================================================
// PART 1: Type System (150줄)
// ============================================================================

struct Type {
    name: string,           // 타입 이름 (i32, string, User, etc.)
    kind: string,           // "primitive" | "struct" | "array" | "function" | "generic" | "tuple"
    parameters: array,      // 제네릭 파라미터 (Type<T, U>)
    methods: dict,          // 메서드 (타입 이름 -> 함수 시그니처)
    traits: array,          // 구현한 트레이트
    size: i32               // 바이트 단위 크기 (최적화용)
}

// 기본 타입 (8개)
fn create_primitive_types() -> dict {
    let mut types = dict;

    // 정수
    types["i32"] = {name: "i32", kind: "primitive", size: 4};
    types["i64"] = {name: "i64", kind: "primitive", size: 8};
    types["u32"] = {name: "u32", kind: "primitive", size: 4};
    types["u64"] = {name: "u64", kind: "primitive", size: 8};

    // 부동소수
    types["f32"] = {name: "f32", kind: "primitive", size: 4};
    types["f64"] = {name: "f64", kind: "primitive", size: 8};

    // 문자열 & 불린
    types["string"] = {name: "string", kind: "primitive", size: -1}; // 동적
    types["bool"] = {name: "bool", kind: "primitive", size: 1};

    return types;
}

// 타입 동등성 (Type Equivalence)
// 두 타입이 같은지 검사
fn types_equal(t1: Type, t2: Type) -> bool {
    if t1.name != t2.name {
        return false;
    }

    // 제네릭 파라미터 개수 확인
    if length(t1.parameters) != length(t2.parameters) {
        return false;
    }

    // 각 파라미터 타입 확인 (재귀)
    let i = 0;
    while i < length(t1.parameters) {
        if !types_equal(t1.parameters[i], t2.parameters[i]) {
            return false;
        }
        i = i + 1;
    }

    return true;
}

// 타입 호환성 (Type Compatibility)
// t1이 t2로 암시 변환 가능한지 확인
fn type_compatible(t1: Type, t2: Type) -> bool {
    // 동등성 먼저 확인
    if types_equal(t1, t2) {
        return true;
    }

    // 자동 변환 규칙
    // i32 -> i64 (승격)
    if t1.name == "i32" && t2.name == "i64" {
        return true;
    }
    // f32 -> f64 (승격)
    if t1.name == "f32" && t2.name == "f64" {
        return true;
    }

    return false;
}

// ============================================================================
// PART 2: Type Inference Engine (150줄)
// ============================================================================

struct TypeEnv {
    vars: dict,             // 변수명 -> 타입
    functions: dict,        // 함수명 -> 함수 타입
    scopes: array           // 스코프 스택
}

fn create_type_env() -> TypeEnv {
    return {
        vars: dict,
        functions: dict,
        scopes: array
    };
}

// 변수 타입 등록
fn bind_var(env: TypeEnv, name: string, type_info: Type) {
    env.vars[name] = type_info;
}

// 변수 타입 조회
fn lookup_var(env: TypeEnv, name: string) -> Type {
    if env.vars[name] != null {
        return env.vars[name];
    }

    return {name: "unknown", kind: "error"};
}

// 타입 추론 메인 함수
// 주어진 AST 노드의 타입을 추론
fn infer_type(env: TypeEnv, node: any) -> Type {
    if node.type == "literal" {
        return infer_literal_type(node);
    } else if node.type == "identifier" {
        return lookup_var(env, node.name);
    } else if node.type == "binary" {
        return infer_binary_type(env, node);
    } else if node.type == "call" {
        return infer_call_type(env, node);
    } else if node.type == "let_stmt" {
        // let x: i32 = 5;
        if node.type_annotation != null {
            return node.type_annotation;
        } else {
            return infer_type(env, node.init);
        }
    }

    return {name: "unknown", kind: "error"};
}

fn infer_literal_type(node: any) -> Type {
    if node.kind == "number" {
        // 정수 또는 실수 판단
        let value = node.value;

        // 단순 휴리스틱: 점이 있으면 f64, 없으면 i32
        if contains(value, ".") {
            return {name: "f64", kind: "primitive"};
        } else {
            return {name: "i32", kind: "primitive"};
        }
    } else if node.kind == "string" {
        return {name: "string", kind: "primitive"};
    } else if node.kind == "bool" {
        return {name: "bool", kind: "primitive"};
    }

    return {name: "unknown", kind: "error"};
}

fn infer_binary_type(env: TypeEnv, node: any) -> Type {
    let left_type = infer_type(env, node.left);
    let right_type = infer_type(env, node.right);

    // 산술 연산자
    if node.operator == "+" || node.operator == "-" || node.operator == "*" || node.operator == "/" {
        // 타입 승격 규칙
        if left_type.name == "f64" || right_type.name == "f64" {
            return {name: "f64", kind: "primitive"};
        }
        return left_type; // 같다고 가정
    }

    // 비교 연산자 (==, !=, <, >, ...)
    if node.operator == "==" || node.operator == "!=" || node.operator == "<" || node.operator == ">" {
        return {name: "bool", kind: "primitive"};
    }

    // 논리 연산자
    if node.operator == "&&" || node.operator == "||" {
        return {name: "bool", kind: "primitive"};
    }

    return {name: "unknown", kind: "error"};
}

fn infer_call_type(env: TypeEnv, node: any) -> Type {
    // 함수명으로 반환 타입 조회
    let fn_name = node.callee.name;
    let fn_type = env.functions[fn_name];

    if fn_type != null {
        return fn_type.return_type;
    }

    return {name: "unknown", kind: "error"};
}

// 문자열 포함 확인 헬퍼
fn contains(str: string, substr: string) -> bool {
    let i = 0;
    while i < length(str) {
        if str[i] == substr {
            return true;
        }
        i = i + 1;
    }
    return false;
}

// ============================================================================
// PART 3: Constraint Propagation & Unification (150줄)
// ============================================================================

struct Constraint {
    kind: string,       // "equals" | "subtype" | "trait" | "frequency"
    lhs: Type,          // 좌측
    rhs: Type           // 우측
}

struct ConstraintStore {
    constraints: array,
    substitutions: dict  // 타입 변수 -> 구체 타입
}

fn create_constraint_store() -> ConstraintStore {
    return {
        constraints: array,
        substitutions: dict
    };
}

// 제약 추가
fn add_constraint(store: ConstraintStore, kind: string, lhs: Type, rhs: Type) {
    push(store.constraints, {kind: kind, lhs: lhs, rhs: rhs});
}

// 단일화 (Unification) - 두 타입을 같게 만들기
fn unify(store: ConstraintStore, t1: Type, t2: Type) -> bool {
    // 이미 같으면 성공
    if types_equal(t1, t2) {
        return true;
    }

    // 타입 변수 치환
    t1 = apply_substitution(store, t1);
    t2 = apply_substitution(store, t2);

    // 다시 확인
    if types_equal(t1, t2) {
        return true;
    }

    // 기본 타입 단일화 실패
    if t1.kind == "primitive" && t2.kind == "primitive" {
        return false;
    }

    // 호환성 확인
    if type_compatible(t1, t2) {
        return true;
    }

    return false;
}

// 제약 전파 및 풀이
fn propagate_constraints(store: ConstraintStore) -> bool {
    let changed = true;

    while changed {
        changed = false;
        let i = 0;

        while i < length(store.constraints) {
            let constraint = store.constraints[i];

            if constraint.kind == "equals" {
                if unify(store, constraint.lhs, constraint.rhs) {
                    // 제약 제거
                    store.constraints[i] = null;
                    changed = true;
                }
            }

            i = i + 1;
        }
    }

    // null 제약 제거
    let mut filtered = array;
    let i = 0;
    while i < length(store.constraints) {
        if store.constraints[i] != null {
            push(filtered, store.constraints[i]);
        }
        i = i + 1;
    }
    store.constraints = filtered;

    // 남은 제약이 없으면 성공
    return length(store.constraints) == 0;
}

// 치환 적용
fn apply_substitution(store: ConstraintStore, t: Type) -> Type {
    if store.substitutions[t.name] != null {
        return apply_substitution(store, store.substitutions[t.name]);
    }

    return t;
}

// ============================================================================
// PART 4: Semantic Analysis (100줄)
// ============================================================================

struct SemanticAnalyzer {
    env: TypeEnv,
    store: ConstraintStore,
    errors: array
}

fn create_semantic_analyzer() -> SemanticAnalyzer {
    return {
        env: create_type_env(),
        store: create_constraint_store(),
        errors: array
    };
}

// AST 노드 검증
fn analyze_node(analyzer: SemanticAnalyzer, node: any) {
    if node.type == "fn_decl" {
        analyze_fn_decl(analyzer, node);
    } else if node.type == "let_stmt" {
        analyze_let_stmt(analyzer, node);
    } else if node.type == "expr_stmt" {
        analyze_expr(analyzer, node.expr);
    }
}

fn analyze_fn_decl(analyzer: SemanticAnalyzer, node: any) {
    // 함수 시그니처 등록
    let fn_type = {
        name: node.name,
        kind: "function",
        params: node.params,
        return_type: node.return_type
    };

    analyzer.env.functions[node.name] = fn_type;

    // 파라미터 바인딩
    let i = 0;
    while i < length(node.params) {
        let param = node.params[i];
        bind_var(analyzer.env, param.name, param.type);
        i = i + 1;
    }

    // 함수 바디 분석
    analyze_block(analyzer, node.body);
}

fn analyze_let_stmt(analyzer: SemanticAnalyzer, node: any) {
    // 초기값 타입 검증
    if node.init != null {
        let init_type = infer_type(analyzer.env, node.init);

        if node.type_annotation != null {
            // 명시적 타입과 초기값 타입이 호환되는지 확인
            if !type_compatible(init_type, node.type_annotation) {
                push(analyzer.errors, {
                    kind: "type_mismatch",
                    expected: node.type_annotation.name,
                    found: init_type.name
                });
            }
        }

        // 변수 바인딩
        bind_var(analyzer.env, node.name, node.type_annotation != null ? node.type_annotation : init_type);
    }
}

fn analyze_expr(analyzer: SemanticAnalyzer, expr: any) {
    let expr_type = infer_type(analyzer.env, expr);

    if expr_type.kind == "error" {
        push(analyzer.errors, {
            kind: "inference_failed",
            expr: expr
        });
    }
}

fn analyze_block(analyzer: SemanticAnalyzer, block: any) {
    let i = 0;
    while i < length(block.statements) {
        analyze_node(analyzer, block.statements[i]);
        i = i + 1;
    }
}

