## 예제: 완전한 타입 안정성 프로그램

```freelang
// 제네릭 컨테이너
struct Box<T> {
    value: T
}

impl<T> Box<T> {
    fn new(value: T) -> Self {
        Box { value }
    }

    fn unwrap(self) -> T {
        self.value
    }
}

// 트레이트
trait Printable {
    fn print(&self);
}

impl Printable for i32 {
    fn print(&self) {
        println!("i32: {}", self);
    }
}

// 함수
fn apply<T: Printable>(item: T) {
    item.print();
}

// 메인
fn main() {
    let boxed_int = Box::new(42);
    let value: i32 = boxed_int.unwrap();  // 타입 안전
    apply(value);  // 타입 체크 완료
}
```

