if score == MAX_POINTS {
    println("Perfect!");
}
```

### 3.4 변수 섀도잉 (Shadowing)

```freelang
let x = 5;
println(x);      // 5

let x = 10;      // 같은 이름으로 재선언
println(x);      // 10

let x = "text";  // 다른 타입도 가능
println(x);      // text

// 유용한 경우
let text = "  hello world  ";
let text = text.trim();      // 공백 제거
let text = text.to_uppercase();  // 대문자
println(text);  // HELLO WORLD
```

### 3.5 스코프 (Scope)

```freelang
let x = 5;

{
    let x = 10;
    println(x);  // 10 (섀도잉)
}

println(x);      // 5 (스코프 밖이므로 원래 값)

// 함수 스코프
fn demonstrate() {
    let y = 20;  // demonstrate 스코프 내에만 존재
}

demonstrate();
println(y);      // 에러! y는 정의되지 않음
```

### 3.6 Best Practices

```freelang
// 좋은 예: 명확한 의도
let mut total = 0;
for i in 1..=5 {
    total = total + i;
}

// 좋은 예: 불변성 선호
let numbers = vec![1, 2, 3, 4, 5];
let sum = numbers.iter().fold(0, |acc, x| acc + x);

// 나쁜 예: 불필요한 가변성
let mut result = 0;
result = 10;  // 한 번만 대입하면 let으로 충분
```

